(()=>{'use strict';
const D=window.CONTEST_PLAN,M=window.ContestRundown,E=M.escape,$=id=>document.getElementById(id),KEY='living-table-chess-rundown-v1';
let state={schema:1,plan:'living-table-chess-2026',hash:D.build.sha256,events:[]},editing=null;
try{const raw=localStorage.getItem(KEY);if(raw)state=M.validate(JSON.parse(raw),D.tasks);}catch{$('storage-warning').textContent='Saved rundown could not be read. Existing storage has not been overwritten. Export any recoverable records before saving new observations.';}
const effective=t=>M.status(D.tasks,state.events,t.id,state.hash);
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('storage-warning').textContent='';}catch{$('storage-warning').textContent='Browser storage failed. Export observations now; this session may otherwise be lost.';}}
function download(name,body,type='application/json'){const u=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function render(){
 $('candidate').value=state.hash;const n=D.tasks.filter(t=>effective(t)==='pass').length;
 $('coverage').textContent=`${n} / ${D.tasks.length} checks passed for this candidate and its prerequisites. This is checklist coverage, not a contest-readiness score.`;$('progress').max=D.tasks.length;$('progress').value=n;
 $('priorities').innerHTML=D.groups.map(g=>{const ts=D.tasks.filter(t=>t.group===g.id),passed=ts.filter(t=>effective(t)==='pass').length;return `<article class="metric"><p class="eyebrow">Priority ${g.id} · ${E(g.window)}</p><strong>${E(g.title)}</strong><p>${E(g.why)}</p><p><b>Exit:</b> ${E(g.gate)}</p><a href="#rundown" data-group="${g.id}">${passed} / ${ts.length} passed · Open checks →</a></article>`;}).join('');
 const q=$('search').value.toLowerCase(),group=$('group').value,status=$('status').value;
 const visible=D.tasks.filter(t=>(group==='all'||String(t.group)===group)&&(status==='all'||(status==='open'?effective(t)!=='pass':effective(t)===status))&&JSON.stringify(t).toLowerCase().includes(q));
 $('checks').innerHTML=visible.map(t=>{const s=effective(t),r=M.latest(state.events,t.id,state.hash,t),missing=t.depends.filter(id=>M.status(D.tasks,state.events,id,state.hash)!=='pass');return `<details class="task" id="check-${t.id}"><summary><span class="meta">${t.id}</span><span class="title"><b>${E(t.title)}</b><br><span class="meta">${E(t.date)} · ${E(t.owner)}</span></span><span class="badge ${s}">${s==='todo'?'Not run':s}</span></summary><div class="body"><ol>${t.steps.map(x=>`<li>${E(x)}</li>`).join('')}</ol><div class="criteria"><b>Pass when</b><p>${E(t.passCriteria)}</p><b>Capture</b><p>${E(t.evidence)}</p></div>${t.baseline?`<p><b>Known baseline:</b> ${E(t.baseline)}</p>`:''}<p class="meta">${t.scope==='build'?'Build-specific check':'Administrative / submission check'} · Prerequisites: ${t.depends.length?t.depends.map(id=>`<a href="#check-${id}" data-jump="${id}">${id}</a>`).join(', '):'none'}${missing.length?' · Still open: '+E(missing.join(', ')):''}</p>${r?`<p class="note">${E(r.note)}</p><p class="meta">${E(r.tester)} · ${E(r.at)}${r.status==='pass'&&s!=='pass'?' · Prior pass blocked by reopened prerequisite':''}</p>`:''}<button data-record="${t.id}">Record result</button></div></details>`;}).join('')||'<p>No checks match these filters.</p>';
 $('history').innerHTML=state.events.length?state.events.slice().reverse().map(r=>`<article class="history"><b>${E(r.id)} · ${E(r.status)}</b> · ${E(r.tester)}<p class="meta">${E(r.at)} · APK ${E(r.hash.slice(0,12))}${r.hash!==state.hash?' · other build':''}</p><p class="note">${E(r.note)}</p></article>`).join(''):'<p>No observations recorded. Automated baseline evidence is not seeded as headset passes.</p>';
}
document.addEventListener('click',e=>{const record=e.target.closest('[data-record]'),group=e.target.closest('[data-group]'),jump=e.target.closest('[data-jump]');if(group){$('group').value=group.dataset.group;render();}if(jump){e.preventDefault();$('group').value='all';$('status').value='all';$('search').value='';render();const el=$('check-'+jump.dataset.jump);el.open=true;el.scrollIntoView({block:'center'});}if(record){editing=D.tasks.find(t=>t.id===record.dataset.record);$('edit-title').textContent=editing.id+' · '+editing.title;$('edit-deps').textContent='Pass requires completed prerequisites: '+(editing.depends.join(', ')||'none');$('note').value='';$('result').value='doing';$('edit-error').textContent='';$('editor').showModal();}});
for(const id of ['group','status','search'])$(id).addEventListener(id==='search'?'input':'change',render);
$('cancel').onclick=()=>$('editor').close();
$('result-form').onsubmit=e=>{e.preventDefault();const status=$('result').value,note=$('note').value.trim(),tester=$('tester').value.trim();if(!note||!tester)return;if(status==='pass'&&editing.depends.some(id=>M.status(D.tasks,state.events,id,state.hash)!=='pass')){$('edit-error').textContent='Finish prerequisite checks first, or record this result as blocked/in progress.';return;}state.events.push({id:editing.id,uid:crypto.randomUUID(),status,note,tester,hash:state.hash,at:new Date().toISOString()});save();$('editor').close();render();};
function candidate(hash){if(!/^[a-f0-9]{64}$/i.test(hash)){$('message').textContent='Enter the complete 64-character APK SHA-256.';return;}state.hash=hash.toLowerCase();save();render();$('message').textContent='Candidate changed. Earlier observations remain in history.';}
$('apply-candidate').onclick=()=>candidate($('candidate').value.trim());$('general-candidate').onclick=()=>candidate(D.build.sha256);$('chess-candidate').onclick=()=>candidate(D.contestBuild.sha256);
$('expand').onclick=()=>document.querySelectorAll('details.task').forEach(d=>d.open=true);
$('export').onclick=()=>download('living-table-chess-observations.json',JSON.stringify(state,null,2));
$('import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>8000000)throw Error('Backup too large.');const imported=M.validate(JSON.parse(await file.text()),D.tasks);const merged=new Map(state.events.map(x=>[x.uid,x]));for(const r of imported.events){if(merged.has(r.uid)&&JSON.stringify(merged.get(r.uid))!==JSON.stringify(r))throw Error('Conflicting observation ID; existing history preserved.');merged.set(r.uid,r);}state.events=[...merged.values()].sort((a,b)=>Date.parse(a.at)-Date.parse(b.at));save();render();$('message').textContent='Backup merged. Current candidate fingerprint was preserved.';}catch(err){$('message').textContent='Import rejected: '+err.message;}finally{e.target.value='';}};
$('download-plan').onclick=()=>{let s=`# ${D.title}\n\nReviewed ${D.revision}. Dates and acceptance targets are proposed. No checks are pre-completed.\n\n`;for(const g of D.groups){s+=`## ${g.id}. ${g.title}\n\n${g.why}\nExit: ${g.gate}\n\n`;for(const t of D.tasks.filter(t=>t.group===g.id)){s+=`- [ ] ${t.id} ${t.title} — ${t.date}; ${t.owner}\n\n`;t.steps.forEach((x,i)=>s+=`  ${i+1}. ${x}\n`);s+=`\n  Pass: ${t.passCriteria}\n  Evidence: ${t.evidence}\n  Prerequisites: ${t.depends.join(', ')||'none'}\n\n`;}}s+='## Sources\n\n'+D.sources.map(x=>`- ${x.title}: ${x.url}`).join('\n');download('Living-Table-Chess-Contest-Checklist.md',s,'text/markdown');};
$('general-build').innerHTML=`0.6.3 · Installed and launched<br><small>${E(D.build.sha256.slice(0,16))}…</small>`;$('chess-build').innerHTML=`0.4.0 · Separate contest profile<br><small>${E(D.contestBuild.sha256.slice(0,16))}…</small>`;$('rules').textContent=D.rules;$('sources').innerHTML=D.sources.map(s=>`<li><a href="${E(s.url)}" target="_blank" rel="noopener">${E(s.title)}</a></li>`).join('');render();
})();
